class Solution { public int[][] onesMinusZeros(int[][] grid){int rows=grid.length,cols=grid[0].length;int[] rowOnes=new int[rows],colOnes=new int[cols];for(int row=0;row<rows;row++)for(int col=0;col<cols;col++)if(grid[row][col]==1){rowOnes[row]++;colOnes[col]++;}int[][] answer=new int[rows][cols];for(int row=0;row<rows;row++)for(int col=0;col<cols;col++)answer[row][col]=2*(rowOnes[row]+colOnes[col])-rows-cols;return answer;} }
